// The resource registry: every resource and subresource the API server serves at the pin, with
// group, version, kind, scope, short names, categories and verbs. Generated by npm run api:vendor
// from the real API server's discovery documents (fixtures/golden/v1.37.2/api/discovery.yaml),
// so it is what `kubectl api-resources` and name resolution see. Static data, parsed once.

import { DATA } from './data/v1.37.2.ts';

export interface ApiResource {
  group: string;
  version: string;
  /** Plural resource name: `deployments`. */
  resource: string;
  /** For a subresource (`deployments/scale` → `scale`). */
  subresource?: string;
  singularName: string;
  kind: string;
  /** The group and version of the subresource's kind when it differs (Scale is autoscaling/v1). */
  kindGroup: string;
  kindVersion: string;
  namespaced: boolean;
  verbs: string[];
  shortNames: string[];
  categories: string[];
  storageVersionHash?: string;
}

export interface ApiGroup {
  name: string;
  versions: string[];
  preferred: string;
}

interface Raw {
  version: string;
  groups: ApiGroup[];
  resources: Record<string, { name: string; singularName: string; namespaced: boolean; kind: string; verbs: string[]; shortNames?: string[]; categories?: string[]; group?: string; version?: string; storageVersionHash?: string }[]>;
}

export interface Registry {
  /** Groups in discovery order: the core group, then /apis order. */
  groups: ApiGroup[];
  /** Every resource and subresource, in discovery order. */
  all: ApiResource[];
  /** `apps/v1` + `deployments` (+ `status`). */
  get(group: string, version: string, resource: string, subresource?: string): ApiResource | undefined;
  /** The resource of a kind in a group version (no subresources). */
  forKind(group: string, version: string, kind: string): ApiResource | undefined;
}

function build(): Registry {
  const raw = JSON.parse(DATA) as Raw;
  const all: ApiResource[] = [];
  const index = new Map<string, ApiResource>();
  const kinds = new Map<string, ApiResource>();
  for (const [gv, list] of Object.entries(raw.resources)) {
    const [group, version] = gv.includes('/') ? (gv.split('/') as [string, string]) : ['', gv];
    for (const r of list) {
      const [resource, subresource] = r.name.split('/') as [string, string | undefined];
      const entry: ApiResource = {
        group,
        version,
        resource,
        ...(subresource !== undefined ? { subresource } : {}),
        singularName: r.singularName,
        kind: r.kind,
        kindGroup: r.group ?? group,
        kindVersion: r.version ?? version,
        namespaced: r.namespaced,
        verbs: r.verbs,
        shortNames: r.shortNames ?? [],
        categories: r.categories ?? [],
        ...(r.storageVersionHash ? { storageVersionHash: r.storageVersionHash } : {}),
      };
      all.push(entry);
      index.set(`${gv}/${r.name}`, entry);
      if (subresource === undefined) kinds.set(`${gv}/${r.kind}`, entry);
    }
  }
  const gvOf = (group: string, version: string) => (group === '' ? version : `${group}/${version}`);
  return {
    groups: raw.groups,
    all,
    get: (group, version, resource, subresource) => index.get(`${gvOf(group, version)}/${resource}${subresource ? `/${subresource}` : ''}`),
    forKind: (group, version, kind) => kinds.get(`${gvOf(group, version)}/${kind}`),
  };
}

let loaded: Registry | undefined;

export function registry(): Registry {
  loaded ??= build();
  return loaded;
}
